$supFishRepeats = FaBSUPCount($player, 'CATCH') > 0 ? 2 : 1;
 for ($supFish = 0; $supFish < $supFishRepeats; $supFish = $supFish + 1) {
 $seaPlayer = $player;

if (FaBFaiHeroHit()) {

 $victim = intval(FaBGetState()['defender']);

$cannon = FaBSEACount($seaPlayer, 'CANNON') > 0;

 $chooser = $cannon ? $seaPlayer : $victim;

 $fishRefs = FaBSEAFishChoices($seaPlayer, $victim, $cannon);

 if ($fishRefs !== '') {

 $chosen = await $chooser.MZChoose($fishRefs, "Go_Fish_choose_and_reveal");

 FaBSEAGoFish($seaPlayer, $victim, $chosen, 'blue_fin_harpoon', $cannon);



}



}


}

